280	    fn run(&self, on_finish_launching: Box<dyn 'static + FnOnce()>) {
281	        let wgpu_context = self.wgpu_context.clone();
282	        let prepared_window = self.prepared_window.clone();
283	        let window_lifecycle = self.window_lifecycle.clone();
284	        let browser_window = self.browser_window.clone();
285	        let backend_preference = self.backend_preference;
286	        wasm_bindgen_futures::spawn_local(async move {
287	            match initialize_graphics(&browser_window, backend_preference).await {
288	                Ok((canvas, context, surface)) => {
289	                    log::info!(
290	                        "Browser graphics initialized successfully with {:?}",
291	                        context.backend()
292	                    );
293	                    *wgpu_context.borrow_mut() = Some(context);
294	                    *prepared_window.borrow_mut() = Some(PreparedWebWindow { canvas, surface });
295	                    on_finish_launching();
296	                }
297	                Err(error) => {
298	                    window_lifecycle.set(WebWindowLifecycle::Unavailable);
299	                    log::error!("Failed to initialize browser graphics: {error:#}");
300	                    show_graphics_unavailable_message(&browser_window, &error);
301	                }
302	            }
303	        });
304	    }
